// Small UI strings, keyed by the language part of `locale`.
const UI_STRINGS = {
  en: { high: 'H', low: 'L', rain: 'RAIN', wind: 'WIND', feelsLike: 'FEELS LIKE', nextDays: 'NEXT 3 DAYS', updated: 'UPDATED', today: 'today' },
  es: { high: 'MÁX', low: 'MÍN', rain: 'LLUVIA', wind: 'VIENTO', feelsLike: 'SENSACIÓN', nextDays: 'PRÓXIMOS 3 DÍAS', updated: 'ACTUALIZADO', today: 'hoy' },
