// Stroke-only (no <text> — SVG text gets no fonts in the renderer).
const ICONS = {
  sun: [
    "<circle cx='12' cy='12' r='4.6'/>",
    "<path d='M12 1.6v2.6'/>", "<path d='M12 19.8v2.6'/>",
    "<path d='M4.65 4.65l1.85 1.85'/>", "<path d='M17.5 17.5l1.85 1.85'/>",
    "<path d='M1.6 12h2.6'/>", "<path d='M19.8 12h2.6'/>",
    "<path d='M4.65 19.35l1.85-1.85'/>", "<path d='M17.5 6.5l1.85-1.85'/>",
